// Import and merge prototyping-expanded modules (Agile, Инструменты, Софт-скилы)
import { prototypingExpandedModules } from "./course-data-prototyping";
// Import and merge extended modules and quizzes
import { extendedModules, capstoneModules, existingModuleQuizzes } from "./course-data-extended";
import { additionalQuizzes, additionalPractice, finalExamQuestions, finalExamCases } from "./course-data-additions";
import { growthModules } from "./course-data-growth";
import { analyticsModules } from "./course-data-analytics";
import { pmfModules } from "./course-data-pmf";

// Apply quizzes and practice to existing modules
courseModules.forEach((module) => {
  module.lessons.forEach((lesson) => {
    if (existingModuleQuizzes[lesson.id]) {
      lesson.quiz = existingModuleQuizzes[lesson.id];
    }
    if (additionalQuizzes[lesson.id] && !lesson.quiz) {
      lesson.quiz = additionalQuizzes[lesson.id];
    }
    if (additionalPractice[lesson.id] && (!lesson.practice || lesson.practice.length === 0)) {
      lesson.practice = additionalPractice[lesson.id];
    }
  });
});

// Merge new modules from course-data-new-modules
import { pricingModule, unitEcoModule, okrModule, gtmModule, legacyModule, prdModule } from "./course-data-new-modules";

// ── MERGE ALL MODULES then SORT by number ────────────────────────────────────
// Modules from this file: m1-m18 (numbers assigned per pedagogical order)
// After push, courseModules.sort() ensures correct display order.
courseModules.push(...prototypingExpandedModules);   // m18b(27), m18c(28), m18d(29)
courseModules.push(...extendedModules);              // m19(34), m20(35)
courseModules.push(...growthModules);                // m-growth(30), m-network(31), m-aiml(32), m-data(15)
courseModules.push(...analyticsModules);             // m-analytics(14)
courseModules.push(...pmfModules);                   // m-pmf(13)
courseModules.push(pricingModule, unitEcoModule);    // m-pricing(24), m-uniteco(23)
courseModules.push(okrModule);                       // m-okr(21)
courseModules.push(gtmModule, legacyModule, prdModule); // m-gtm(22), m-legacy(33), m-prd(26)
courseModules.push(...capstoneModules);              // m21(36), m-sim(37), m22(38)

// Sort all modules by number for correct pedagogical order (easy → complex)
courseModules.sort((a, b) => a.number - b.number);

// Apply additional quizzes/practice to extended modules too
courseModules.forEach((module) => {
  module.lessons.forEach((lesson) => {
    if (additionalQuizzes[lesson.id] && !lesson.quiz) {
      lesson.quiz = additionalQuizzes[lesson.id];
    }
    if (additionalPractice[lesson.id] && (!lesson.practice || lesson.practice.length === 0)) {
      lesson.practice = additionalPractice[lesson.id];
    }
  });
});

// ── Strip em-dashes from all text content ──────────────────────────────────
// Replaces "—" (U+2014) with "-" across all modules, lessons, quizzes, etc.
function _stripEm(s: string): string {
  return s.replace(/—/g, "-");
}
courseModules.forEach(mod => {
  mod.title = _stripEm(mod.title);
  mod.description = _stripEm(mod.description);
  mod.lessons.forEach(lesson => {
    lesson.title = _stripEm(lesson.title);
    lesson.content = lesson.content.map(_stripEm);
    if (lesson.keyPoints) lesson.keyPoints = lesson.keyPoints.map(_stripEm);
    if (lesson.examples) lesson.examples = lesson.examples.map(_stripEm);
    if (lesson.practice) lesson.practice = lesson.practice.map(_stripEm);
    if (lesson.quiz) lesson.quiz = lesson.quiz.map(q => ({
      ...q,
      question: _stripEm(q.question),
      options: q.options.map(_stripEm),
      explanation: q.explanation ? _stripEm(q.explanation) : q.explanation,
    }));
  });
});
// ─────────────────────────────────────────────────────────────────────────────

// Export final exam
export { finalExamQuestions, finalExamCases };

export function getTotalLessons(): number {
  return courseModules.reduce((acc, m) => acc + m.lessons.length, 0);
}

// Module-level cache — courseModules is a constant, safe to cache indefinitely
let _allLessonsCache: { module: Module; lesson: Lesson }[] | null = null;

export function getAllLessons(): { module: Module; lesson: Lesson }[] {
  if (!_allLessonsCache) {
    _allLessonsCache = courseModules.flatMap(m =>
      m.lessons.map(l => ({ module: m, lesson: l }))
    );
  }
  return _allLessonsCache;
}

/** Shared unlock predicate — module is unlocked when the previous module is fully completed */
export function isModuleUnlocked(module: Module, completedLessons: Set<string>): boolean {
  const mi = courseModules.findIndex(m => m.id === module.id);
  return (
    mi === 0 ||
    (mi > 0 && courseModules[mi - 1].lessons.every(l => completedLessons.has(l.id)))
  );
}

